import React, { useEffect, useState } from 'react';
import axios from 'axios';

const fallback = [
  { id: 1, title: 'Nivel Básico', content: 'hola mundo esta es una prueba de mecanografia' },
  { id: 2, title: 'Teclas comunes', content: 'asdf jkl; asdf jkl; asdf jkl;' },
  { id: 3, title: 'Frase larga', content: 'la practica hace al maestro, escribe con calma y constancia' },
];

const ContentList = () => {
  const [content, setContent] = useState(fallback);

  useEffect(() => {
    const fetchContent = async () => {
      try {
        if (!axios) throw new Error('axios no disponible');
        const response = await axios.get('/api/content');
        if (response && response.data && response.data.length) setContent(response.data);
      } catch (error) {
        // No hay backend: usamos lista por defecto
        console.warn('Usando contenido local por defecto:', error.message || error);
      }
    };

    fetchContent();
  }, []);

  return (
    <div>
      {content.map(item => (
        <article key={item.id} style={{ borderBottom: '1px solid #eee', padding: '0.5rem 0' }}>
          <h3>{item.title}</h3>
          <p style={{ whiteSpace: 'pre-wrap' }}>{item.content}</p>
        </article>
      ))}
    </div>
  );
};

export default ContentList;
